test('lineTotal: does not mutate input', () => {
  const line = { qty: 5, unitPrice: 9500 };
  const lineCopy = JSON.parse(JSON.stringify(line));
  lineTotal(line);
  assert.deepEqual(line, lineCopy);
});

test('invoiceTotals: single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 47500);
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, vatRate: 0 },
      { qty: 3, unitPrice: 8500, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 25500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 73000);
});

test('invoiceTotals: many lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, vatRate: 0 },
      { qty: 2, unitPrice: 200, vatRate: 0 },
      { qty: 3, unitPrice: 300, vatRate: 0 },
      { qty: 4, unitPrice: 400, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100 + 400 + 900 + 1600);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 3000);
});

test('invoiceTotals: with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals: does not mutate input', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 0 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  invoiceTotals(invoice);
  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals: with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier, 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 8 * 9500 + 5 * 8500; // 118500
  const vat = 8 * 9500 * 0.21 + 5 * 8500 * 0.21; // 24885
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 24885);
  assert.equal(totals.total, 143385);
});

test('addLine: adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Design work (hour)');
});

test('addLine: increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine: rejects invalid qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 2.5 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('addLine: rejects zero qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 0 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('addLine: rejects unknown SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'UNKNOWN', qty: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('addLine: rejects draft status requirement', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  invoice.status = 'sent';

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('addLine: does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.deepEqual(invoiceResult.value, original);
});

test('removeLine: removes a line from an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const result = removeLine(invoiceResult.value, 'DEV-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
});

test('removeLine: rejects removing the last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = removeLine(invoiceResult.value, 'DEV-HOUR');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('removeLine: rejects non-existent SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = removeLine(invoiceResult.value, 'UNKNOWN');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'LINE_NOT_FOUND');
});

test('removeLine: rejects draft status requirement', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const invoice = invoiceResult.value;
  invoice.status = 'paid';

  const result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('removeLine: does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  removeLine(invoiceResult.value, 'DES-HOUR');
  assert.deepEqual(invoiceResult.value, original);
});

test('addLine and removeLine: can chain operations', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);

  result = addLine(result.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);

  result = removeLine(result.value, 'DES-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].sku, 'COPY-HOUR');
});

test('issueInvoice: issues a draft invoice with a number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = issueInvoice(invoiceResult.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.lines.length, 1);
});

test('issueInvoice: assigns sequential numbers for the same year', () => {
  const invoiceResult1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issued1 = issueInvoice(invoiceResult1.value, []);
  assert.equal(issued1.value.number, 'INV-2026-0001');

  const invoiceResult2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });

  const issued2 = issueInvoice(invoiceResult2.value, [issued1.value.number]);
  assert.equal(issued2.value.number, 'INV-2026-0002');
});

test('issueInvoice: uses different numbers for different years', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issued1 = issueInvoice(invoice1.value, []);
  assert.equal(issued1.value.number, 'INV-2025-0001');

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issued2 = issueInvoice(invoice2.value, [issued1.value.number]);
  assert.equal(issued2.value.number, 'INV-2026-0001');
});

test('issueInvoice: rejects non-draft status', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  invoice.status = 'issued';

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice: does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const original = JSON.parse(JSON.stringify(invoiceResult.value));
  issueInvoice(invoiceResult.value, []);
  assert.deepEqual(invoiceResult.value, original);
});

test('issueInvoice: preserves all invoice properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
